module protocol::asset_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::interest::InterestModel;
use protocol::asset::AssetConfig;

const ASSET_MARKET_CONFIG: u8 = 0;
const ASSET_INTEREST_MODEL: u8 = 1;
const ASSET_BORROW_PAUSE_STATE: u8 = 2;
// fource more fields reserved, 3 - 6

const DECIMAL_DENOMINATOR: u64 = 10000;
const PRICISE_DECIMAL_DENOMINATOR: u64 = 1000000000000000000;

public struct AssetOnboardedEvent has copy, drop {
    market: TypeName,
    interest_model: InterestModel,
    asset_config: AssetConfig,
    time: u64,
    operator: address,
}

public struct AssetUpdated<T> has copy, drop {
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun onboard_new_asset<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    interest_model: InterestModel,
    asset_config: AssetConfig,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let now = clock.timestamp_ms() / 1000;
    market.onboard_new_asset<MarketType, CoinType>(
        interest_model,
        asset_config,
        now,
        ctx,
    );


    emit(AssetOnboardedEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        interest_model,
        asset_config,
        time: now,
        operator: ctx.sender(),
    });
}

/// Create a asset configuration
public fun create_market_asset_config(
    _: &AdminCap,
    self: &ProtocolApp,
    min_borrow_amount: u64,
    max_borrow_amount: u64,
    max_deposit_amount: u64,
    repay_fee_rate: u64, // basis points
    liquidation_fee_rate: u64, // basis points
): AssetConfig {
    // Validate parameters
    assert!(min_borrow_amount > 0, error::invalid_params_error());
    assert!(liquidation_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());
    assert!(repay_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());

    self.ensure_version_matches();

    let liquidation_fee = math::float::from_quotient(liquidation_fee_rate, DECIMAL_DENOMINATOR);
    let repay_fee = math::float::from_quotient(repay_fee_rate, DECIMAL_DENOMINATOR);

    protocol::asset::new_asset_config(
        min_borrow_amount,
        max_borrow_amount,
        repay_fee,
        max_deposit_amount,
        liquidation_fee
    )
}

/// Update borrow configuration for an asset
public fun update_market_asset_config<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    asset_config: AssetConfig,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.update_asset_config<MarketType>(asset_config);

    emit(AssetUpdated<AssetConfig>{
        what: ASSET_MARKET_CONFIG,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: asset_config
    });
}

public fun update_market_asset_interest_model<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    interest_model: InterestModel,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.update_interest_model<MarketType>(interest_model);

    emit(AssetUpdated<InterestModel>{
        what: ASSET_INTEREST_MODEL,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: interest_model
    });
}

public fun update_asset_paused_state<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    what: u8,
    is_paused: bool
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.change_operation_status<MarketType>(what, is_paused);

    emit(AssetUpdated<bool>{
        what: ASSET_BORROW_PAUSE_STATE + what,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: is_paused,
    });
}

/// Create an interest model
public fun create_interest_model(
    admin_cap: &AdminCap,
    self: &ProtocolApp,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    assert!(mid_kink > 0, error::invalid_params_error());
    assert!(mid_kink < high_kink && high_kink < DECIMAL_DENOMINATOR, error::invalid_params_error());
    assert!(base_rate_per_sec <= borrow_rate_on_mid_kink, error::invalid_params_error());
    assert!(borrow_rate_on_mid_kink <= borrow_rate_on_high_kink && borrow_rate_on_high_kink <= max_borrow_rate, error::invalid_params_error());

    self.ensure_version_matches();

    create_interest_model_inner(admin_cap, base_rate_per_sec, borrow_rate_on_mid_kink, mid_kink, borrow_rate_on_high_kink, high_kink, max_borrow_rate)
}

fun create_interest_model_inner(
    _: &AdminCap,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    // Convert u64 values to UQ64_64 for the interest model
    let base_rate = math::float::from_quotient(base_rate_per_sec, PRICISE_DECIMAL_DENOMINATOR);
    let mid_kink_rate = math::float::from_quotient(
        borrow_rate_on_mid_kink,
        PRICISE_DECIMAL_DENOMINATOR,
    );
    let mid_kink_util = math::float::from_quotient(mid_kink, DECIMAL_DENOMINATOR);
    let high_kink_rate = math::float::from_quotient(
        borrow_rate_on_high_kink,
        PRICISE_DECIMAL_DENOMINATOR,
    );
    let high_kink_util = math::float::from_quotient(high_kink, DECIMAL_DENOMINATOR);
    let max_rate = math::float::from_quotient(max_borrow_rate, PRICISE_DECIMAL_DENOMINATOR);

    protocol::interest::new(
        base_rate,
        mid_kink_rate,
        mid_kink_util,
        high_kink_rate,
        high_kink_util,
        max_rate,
    )
}

// allow testing interest rate much larger than production allowed 
#[test_only]
public fun create_interest_model_test(
    admin_cap: &AdminCap,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    create_interest_model_inner(admin_cap, base_rate_per_sec, borrow_rate_on_mid_kink, mid_kink, borrow_rate_on_high_kink, high_kink, max_borrow_rate)
}

module protocol::emode_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::limiter::NewLimiter;
use protocol::emode::{new_emode_params, NewEMode};

const EMODE_CREATED: u8 = 0;
const EMODE_UPDATED: u8 = 1;

const BPS_DENOMINATOR: u64 = 10000;

public struct NewEModeGroupEvent has copy, drop {
    market: TypeName,
    emode_group_id: u8,
    oracle_base_token: u8,
    time: u64,
    operator: address,
}

public struct EModeUpdated<T> has copy, drop {
    who: address,
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun create_limiter(
    _: &AdminCap,
    self: &ProtocolApp,
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
): protocol::limiter::NewLimiter {
    self.ensure_version_matches();

    protocol::limiter::create_new_limiter_change(outflow_limit, outflow_cycle_duration, outflow_segment_duration)
}

public fun onboard_new_emode_group<MarketType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    oracle_base_token: u8,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let id = market.emode_registry_mut().new_emode_group(oracle_base_token, ctx);
    let now = clock.timestamp_ms() / 1000;

    emit(NewEModeGroupEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        emode_group_id: id,
        oracle_base_token,
        time: now,
        operator: ctx.sender(),
    });
}

public fun create_emode_params(
    cap: &AdminCap,
    self: &ProtocolApp,

    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < liquidation_factor_bps, error::invalid_params_error());
    assert!(liquidation_factor_bps - collateral_factor_bps < liquidation_incentive_bps, error::invalid_params_error());

    self.ensure_version_matches();

    // liquidation factor * (1 + liquidation incentive) < 1
    assert!(
        liquidation_factor_bps * (BPS_DENOMINATOR + liquidation_incentive_bps) / BPS_DENOMINATOR < BPS_DENOMINATOR,
        error::invalid_params_error()
    );

    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

public fun onboard_asset_to_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    market.emode_registry_mut().support_asset<CoinType>(group, params, ctx);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_CREATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        who: ctx.sender(),
        new: params
    });
}

public fun update_asset_in_emode_group<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    group: u8,
    params: NewEMode,
    ctx: &TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let asset = std::type_name::with_defining_ids<CoinType>();
    let emode = market.emode_registry_mut().borrow_mut_emode(group, asset);
    emode.update(params);

    emit(EModeUpdated<NewEMode>{
        what: EMODE_UPDATED,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset,
        who: ctx.sender(),
        new: params
    });
}

fun create_emode_params_inner(
    _: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    assert!(collateral_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_factor_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(liquidation_incentive_bps < BPS_DENOMINATOR, error::invalid_params_error());
    assert!(borrow_weight_bps >= BPS_DENOMINATOR, error::invalid_params_error());
    assert!(flash_loan_fee_rate_bps < BPS_DENOMINATOR, error::invalid_params_error());

    let collateral_factor = math::float::from_quotient(collateral_factor_bps, BPS_DENOMINATOR);
    let liquidation_factor = math::float::from_quotient(liquidation_factor_bps, BPS_DENOMINATOR);
    let liquidation_incentive = math::float::from_quotient(liquidation_incentive_bps, BPS_DENOMINATOR);
    let borrow_weight = math::float::from_quotient(borrow_weight_bps, BPS_DENOMINATOR);
    let flash_loan_fee_rate = math::float::from_quotient(flash_loan_fee_rate_bps, BPS_DENOMINATOR);

    new_emode_params(
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,
        max_borrow_amount,
        borrow_weight,
        flash_loan_fee_rate,
        deposit_limiter,
        borrow_limiter,
    )
}

#[test_only]
public fun create_emode_params_test(
    cap: &AdminCap,
    collateral_factor_bps: u64,
    liquidation_factor_bps: u64,
    liquidation_incentive_bps: u64,

    max_borrow_amount: u64,
    borrow_weight_bps: u64,

    flash_loan_fee_rate_bps: u64,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    create_emode_params_inner(
        cap,
        collateral_factor_bps,
        liquidation_factor_bps,
        liquidation_incentive_bps,
        max_borrow_amount,
        borrow_weight_bps,
        flash_loan_fee_rate_bps,
        deposit_limiter,
        borrow_limiter
    )
}

